import { describe, expect, it } from "vitest";
import { quote } from "./claim-office.js";

describe("MHPCO quote -- base premiums", () => {
  it("empty item list -> premium 5 G (processing fee only)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [])).toBe(5);
  });
  it.todo("single sword -> base premium 100 G");
  it.todo("single amulet -> base premium 60 G");
  it.todo("single staff -> base premium 80 G");
  it.todo("single potion -> base premium 40 G");
  it.todo("single rune (component) -> base premium 25 G");
  it.todo("single moonstone (component) -> base premium 25 G");
});

describe("MHPCO quote -- component building blocks", () => {
  it.todo("2 runes -> 50 G base premium (no block)");
  it.todo("3 runes -> 60 G base premium (block applies)");
  it.todo("4 runes -> 100 G base premium (no block -- block requires exactly 3)");
  it.todo("7 runes -> 175 G base premium (no block -- 7 is not exactly 3)");
  it.todo("2 runes + 1 moonstone -> 75 G base premium (no block: 'alike' means same type)");
  it.todo("3 runes + 3 moonstones -> 120 G base premium (two separate blocks)");
});

describe("MHPCO quote -- item-specific modifiers", () => {
  it.todo("cursed sword -> 50 % surcharge on that item's base premium");
  it.todo("sword with enchantment 5 -> 30 % high-enchantment surcharge (threshold inclusive)");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 -> both surcharges apply");
  it.todo(
    "cursed sword + plain amulet -> 210 G before policy modifiers and fee (curse applies to the cursed item only, not the policy total)",
  );
});

describe("MHPCO quote -- policy-wide modifiers", () => {
  it.todo("customer with exactly 2 years -> 20 % loyalty discount applies (threshold inclusive)");
  it.todo("customer with 1 year -> no loyalty discount");
  it.todo("first insurance -> 10 % initial assessment surcharge on the policy base premium");
  it.todo("second quote in a scenario -> 15 % follow-up contract discount");
  it.todo("processing fee of 5 G is added at the very end, after all modifiers");
});

describe("MHPCO quote -- rounding in the MHPCO's favor", () => {
  it.todo("premium of 197.5 G -> 198 G (rounded up)");
  it.todo("intermediate amounts stay fractional; only the final premium is rounded");
});

describe("MHPCO quote -- integration examples", () => {
  it.todo("newcomer (0 years) with a cursed sword (steel, ench 3) -> premium 165 G");
  it.todo(
    "long-standing customer (3 years), second quote, cursed sword ench 7 -> premium 160 G (first-insurance surcharge still applies)",
  );
});

describe("MHPCO quote -- errors", () => {
  it.todo("item with an unknown type (e.g. broomstick) -> throws an Error (CLI exits non-zero, message on stderr)");
});

describe("MHPCO claim -- standard reimbursement", () => {
  it.todo("regular sword (steel, ench 3), damage 500 G -> payout 400 G (full minus 100 G deductible)");
  it.todo("rune (no enchantment, no material), damage 200 G -> payout 100 G");
  it.todo("damage below the deductible -> payout is not negative (clamped at 0 G)");
});

describe("MHPCO claim -- special clauses", () => {
  it.todo("steel sword, enchantment 9, damage 1000 G -> payout 400 G (50 % clause, then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G -> payout 700 G (full reimbursement, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G -> payout 400 G (50 % rule wins over dragon material)");
  it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G -> payout 400 G (threshold inclusive)");
});

describe("MHPCO claim -- deductible per damage event", () => {
  it.todo("sword (500 G) and amulet (300 G) damaged in one incident -> payout 600 G (deductible once per damaged item)");
});

describe("MHPCO claim -- insurance sum and cap", () => {
  it.todo("policy with sword + amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("policy with a cursed sword -> cap 2000 G (based on unmodified insurance value)");
  it.todo("policy with sword + 3 runes -> insurance sum 1750 G (block discount affects the premium only)");
  it.todo("policy with two swords -> insurance sum 2000 G, cap 4000 G");
  it.todo("sword policy (cap 2000 G), first claim of 1500 G -> payout 1400 G, remainingCap 600 G");
  it.todo("sword policy, second claim of 1500 G after the first -> payout 600 G, remainingCap 0 G (capped)");
});

describe("MHPCO claim -- multiple items of the same type", () => {
  it.todo("two swords insured, two sword damages -> each damage gets its own deductible");
  it.todo("two sword damages but only one sword insured -> throws an Error (CLI exits non-zero)");
});

describe("MHPCO claim -- errors", () => {
  it.todo("damage to an item not covered by the policy (amulet, only a sword insured) -> throws an Error");
  it.todo("damage entry with an unknown item type -> throws an Error");
  it.todo("damage entry with amount -200 -> throws an Error");
});

describe("MHPCO claim -- rounding in the MHPCO's favor", () => {
  it.todo("payout of 350.5 G -> 350 G (rounded down)");
});

describe("MHPCO scenario runner", () => {
  it.todo("processes steps sequentially and returns results in the same order and length");
  it.todo("a claim step references its policy by the zero-based index of the quote step");
  it.todo("schema example: amulet quote then 200 G fire claim -> premium and payout/remainingCap results");
});

describe("claim-office CLI", () => {
  it.todo("reads a scenario from stdin and writes {results: [...]} JSON to stdout");
  it.todo("unknown item type -> exit code non-zero, error description on stderr, no results on stdout");
  it.todo("negative damage amount -> exit code non-zero, error description on stderr");
});

