83	export function policyBasePremium(items: Item[]): number {
84	  return sumPolicy(items, itemPremium);
85	}
86	
87	/**
88	 * The sum of the items' unmodified base premiums. Policy-wide modifiers
89	 * (loyalty, first insurance, follow-up contract) are percentages of this
90	 * amount, not of the item-modified subtotal -- see the spec's integration
91	 * examples, where the surcharges are 10 % and 20 % of 100 G, not of 150 G.
92	 */
93	function unmodifiedBasePremium(items: Item[]): number {
94	  return sumPolicy(items, basePremiumOf);
95	}
96	
97	export interface QuoteStep {
98	  op: "quote";
99	  items: Item[];
100	}
101	
102	export interface Damage {
103	  itemType: string;
104	  amount: number;
105	}
106	
107	export interface Incident {
108	  cause: string;
109	  damages: Damage[];
110	}
111	
112	export interface ClaimStep {
113	  op: "claim";
114	  policy: number;
115	  incident: Incident;
116	}
