118	export type Step = QuoteStep | ClaimStep;
119	
120	export interface Scenario {
121	  customer: Customer;
122	  steps: Step[];
123	}
124	
125	export interface QuoteResult {
126	  premium: number;
127	}
128	
129	export interface ClaimResult {
130	  payout: number;
131	  remainingCap: number;
132	}
133	
134	export type StepResult = QuoteResult | ClaimResult;
135	
136	// Policy-wide modifier rates, applied to the unmodified base premium sum.
137	const LOYALTY_YEARS = 2;
138	const LOYALTY_DISCOUNT_RATE = 0.2;
139	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
140	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
141	
142	export function quote(customer: Customer, items: Item[], isFollowUpContract = false): number {
143	  const withItemModifiers = policyBasePremium(items);
144	  const unmodifiedBase = unmodifiedBasePremium(items);
145	  const loyaltyDiscount =
146	    customer.yearsWithMHPCO >= LOYALTY_YEARS ? unmodifiedBase * LOYALTY_DISCOUNT_RATE : 0;
147	  const firstInsuranceSurcharge = unmodifiedBase * FIRST_INSURANCE_SURCHARGE_RATE;
148	  const followUpDiscount = isFollowUpContract ? unmodifiedBase * FOLLOW_UP_DISCOUNT_RATE : 0;
149	  const premium =
150	    withItemModifiers - loyaltyDiscount + firstInsuranceSurcharge - followUpDiscount + PROCESSING_FEE;
151	  return Math.ceil(premium);
152	}
153	
154	const DEDUCTIBLE = 100;
155	const CAP_FACTOR = 2;
156	const COMPONENT_INSURANCE_VALUE = 250;
157	
158	const INSURANCE_VALUES: Record<string, number> = {
159	  sword: 1000,
160	  amulet: 600,
161	  staff: 800,
162	  potion: 400,
163	  rune: COMPONENT_INSURANCE_VALUE,
164	  moonstone: COMPONENT_INSURANCE_VALUE,
165	};
166	
167	function insuranceValueOf(item: Item): number {
168	  return lookupByType(INSURANCE_VALUES, item);
169	}
170	
171	export function insuranceSum(items: Item[]): number {
172	  return items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
173	}
174	
175	interface Policy {
176	  items: Item[];
177	  remainingCap: number;
178	}
179	
180	const REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
181	const REDUCED_REIMBURSEMENT_RATE = 0.5;
182	
183	function damagePayout(damage: Damage, item: Item): number {
184	  const reduced = (item.enchantment ?? 0) >= REIMBURSEMENT_ENCHANTMENT_LEVEL;
185	  const reimbursed = reduced ? damage.amount * REDUCED_REIMBURSEMENT_RATE : damage.amount;
186	  return Math.max(0, reimbursed - DEDUCTIBLE);
187	}
188	
189	/**
190	 * Matches each damage entry to a distinct insured item. A policy covering one
191	 * sword cannot absorb two sword damages -- the spec rejects the whole claim.
192	 */
193	function matchDamagesToItems(policy: Policy, damages: Damage[]): { damage: Damage; item: Item }[] {
194	  const available = [...policy.items];
195	  return damages.map((damage) => {
196	    if (damage.amount < 0) {
197	      throw new Error(`Damage amount must not be negative: ${String(damage.amount)}`);
198	    }
199	    const index = available.findIndex((candidate) => candidate.type === damage.itemType);
200	    if (index === -1) {
201	      throw new Error(`Damaged item is not covered by the policy: ${damage.itemType}`);
202	    }
203	    const [item] = available.splice(index, 1);
204	    return { damage, item };
205	  });
206	}
207	
208	function settleClaim(policy: Policy, incident: Incident): ClaimResult {
209	  const matched = matchDamagesToItems(policy, incident.damages);
210	  const desired = matched.reduce((sum, { damage, item }) => sum + damagePayout(damage, item), 0);
211	  const payout = Math.floor(Math.min(desired, policy.remainingCap));
212	  policy.remainingCap -= payout;
213	  return { payout, remainingCap: policy.remainingCap };
214	}
215	
216	export function runScenario(scenario: Scenario): StepResult[] {
217	  const policies = new Map<number, Policy>();
218	  let quoteCount = 0;
219	
220	  return scenario.steps.map((step, index) => {
221	    if (step.op === "claim") {
222	      const policy = policies.get(step.policy);
223	      if (policy === undefined) {
224	        throw new Error(`Claim references unknown policy at step ${String(step.policy)}`);
225	      }
226	      return settleClaim(policy, step.incident);
227	    }
228	    const premium = quote(scenario.customer, step.items, quoteCount > 0);
229	    quoteCount += 1;
230	    policies.set(index, { items: step.items, remainingCap: insuranceSum(step.items) * CAP_FACTOR });
231	    return { premium };
232	  });
233	}
